<?php
require __DIR__.'/../app/bootstrap.php'; require_admin(); require __DIR__.'/../app/admin-layout.php';
$search=is_string($_GET['q'] ?? null)?substr(trim($_GET['q']),0,100):''; $filter=is_string($_GET['filter'] ?? null)?$_GET['filter']:'';
$where=[]; $params=[];
if ($search!=='') {$where[]='(name LIKE ? OR producer LIKE ? OR batch_code LIKE ?)';$params=['%'.$search.'%','%'.$search.'%','%'.$search.'%'];}
if($filter==='low') $where[]='stock<=min_stock AND active=1';
if($filter==='expiry') $where[]='expires_on<=DATE_ADD(CURRENT_DATE,INTERVAL 3 DAY) AND stock>0';
if($filter==='inactive') $where[]='active=0';
$sql=$where?' WHERE '.implode(' AND ',$where):'';
$count=(int)query('SELECT COUNT(*) FROM products'.$sql,$params)->fetchColumn();
$pages=max(1,(int)ceil($count/30));$page=min($pages,max(1,(int)($_GET['page'] ?? 1)));$offset=($page-1)*30;
$products=query('SELECT * FROM products'.$sql.' ORDER BY active DESC,name LIMIT 30 OFFSET '.$offset,$params)->fetchAll();
page_start('Estoque','inventory'); ?>
<div class="section-heading"><p class="lead">Saldo disponível, origem e validade de cada alimento.</p><a class="button" href="product.php">+ Novo produto</a></div>
<form class="filters" method="get"><label class="grow">Buscar produto, produtor ou lote<input type="search" name="q" value="<?= e($search) ?>" placeholder="Ex.: alface"></label><label>Mostrar<select name="filter"><option value="">Todos os produtos</option><?php foreach(['low'=>'Estoque baixo','expiry'=>'Validade próxima / vencidos','inactive'=>'Inativos'] as $k=>$v): ?><option value="<?= $k ?>" <?= $filter===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label><button class="button">Filtrar</button><a class="button secondary" href="inventory.php">Limpar</a></form>
<section class="panel"><div class="section-heading"><h2>Alimentos cadastrados</h2><span class="muted"><?= $count ?> produto(s)</span></div><p class="small muted">O saldo disponível já desconta os pedidos reservados. Quantidades são pacotes/unidades inteiras.</p><div class="table-wrap"><table><thead><tr><th>Produto / origem</th><th>Preço</th><th>Disponível</th><th>Validade</th><th>Situação</th><th></th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><small><?= e($p['producer']) ?> · <?= e($p['unit']) ?></small><small>Lote: <?= e($p['batch_code'] ?: 'Não informado') ?></small></td><td><?= brl($p['price_cents']) ?></td><td><strong><?= (int)$p['stock'] ?></strong><small>Mínimo: <?= (int)$p['min_stock'] ?></small></td><td><?= $p['expires_on']?date('d/m/Y',strtotime($p['expires_on'])):'Não informada' ?></td><td><?php if(!$p['active']): ?><span class="pill">Inativo</span><?php elseif($p['expires_on'] && $p['expires_on']<date('Y-m-d')): ?><span class="pill cancelado">Vencido</span><?php elseif((int)$p['stock']<=(int)$p['min_stock']): ?><span class="pill recebido">Estoque baixo</span><?php else: ?><span class="pill concluido">Disponível</span><?php endif; ?></td><td><a class="button secondary compact" href="product.php?id=<?= (int)$p['id'] ?>">Gerenciar →</a></td></tr><?php endforeach; ?><?php if(!$products): ?><tr><td colspan="6" class="empty">Nenhum produto encontrado. Cadastre um alimento para começar.</td></tr><?php endif; ?></tbody></table></div><nav class="pagination" aria-label="Paginação"><?php if($page>1): ?><a href="?<?= e(http_build_query(['q'=>$search,'filter'=>$filter,'page'=>$page-1])) ?>">← Anterior</a><?php endif; ?><span>Página <?= $page ?> de <?= $pages ?></span><?php if($page<$pages): ?><a href="?<?= e(http_build_query(['q'=>$search,'filter'=>$filter,'page'=>$page+1])) ?>">Próxima →</a><?php endif; ?></nav></section>
<?php page_end(); ?>
